import urllib.request,json,os,time
for endpoint in ['results','qualifying']:
 allr=[]
 for off in range(0,500,100):
  url=f'https://api.jolpi.ca/ergast/f1/2026/{endpoint}.json?limit=100&offset={off}'
  d=json.load(urllib.request.urlopen(url))
  races=d['MRData']['RaceTable']['Races']
  print(endpoint,off,len(races),sum(len(r.get('Results',r.get('QualifyingResults',[]))) for r in races))
  # merge race records keyed round
  for r in races:
   key=r['round']
   found=next((x for x in allr if x['round']==key),None)
   field='Results' if endpoint=='results' else 'QualifyingResults'
   if found: found[field].extend(r[field])
   else: allr.append(r)
  if off+100>=int(d['MRData']['total']):break
 json.dump(allr,open(f'/workspace/data/{endpoint}_races.json','w'),indent=2)
 print('merged',[(r['round'],r['raceName'],len(r.get('Results',r.get('QualifyingResults',[])))) for r in allr])
PY"}

